<script lang="ts">
 import { saveOffline } from '../offline-vault';
 let {url,title,mime}:{url:string;title:string;mime:string}=$props();let phrase=$state('');let busy=$state(false);let progress=$state('');let error=$state('');let controller:AbortController|undefined;
 async function download(event:SubmitEvent){event.preventDefault();controller=new AbortController();busy=true;error='';try{await saveOffline(url,title,mime,phrase,controller.signal,(bytes,total)=>progress=`${Math.floor(bytes/total*100)} %`);progress='Disponible dans Téléchargements.';}catch(cause){error=cause instanceof Error?cause.message:'Téléchargement impossible.';}finally{busy=false;phrase='';}}
</script>
<details><summary>Télécharger pour une lecture hors ligne</summary><form onsubmit={download}><p>Copie locale chiffrée, 4 Gio maximum. Une copie déjà téléchargée reste utilisable hors connexion après révocation de la session serveur. Supprimez-la sur un appareil partagé.</p><label>Phrase de déverrouillage (à conserver)<input type="password" autocomplete="new-password" minlength="12" required bind:value={phrase} disabled={busy} /></label><button disabled={busy}>Télécharger cette version originale</button>{#if busy}<button type="button" onclick={()=>controller?.abort()}>Annuler</button>{/if}<p role="status">{progress}</p>{#if error}<p role="alert">{error}</p>{/if}</form></details>
<style>details { margin:16px 0; } form,label { display:grid;gap:10px; } input,button { background:var(--color-surface);color:var(--color-text);border:1px solid var(--color-line);border-radius:8px;padding:10px; } </style>
